                <?php foreach($languages as$language):$locale=(string)$language['locale'];$translation=(array)($editing['translations'][$locale]??[]); ?><section data-language-panel="<?= $escape($locale) ?>" <?= $locale!==$activeLocale?'hidden':'' ?>><div class="sensecms-editor-language-head"><img src="<?= $escape($language['flag']?:'/sensecms/images/flags/gb.svg') ?>" alt=""><div><strong><?= $escape($language['native_name']?:$language['name']) ?></strong><span><?= $locale===$defaultLocale?$uiText('Default language · required'):$uiText('Localized content · optional until completed') ?></span></div></div><div class="grid gap-4"><label><span><?= $escape($uiText('Category name')) ?></span><input class="form-input" maxlength="150" name="translations[<?= $escape($locale) ?>][name]" value="<?= $escape($translation['name']??'') ?>" <?= $locale===$defaultLocale?'required':'' ?>></label><label><span><?= $escape($uiText('Description')) ?></span><textarea class="form-input" maxlength="1000" rows="5" name="translations[<?= $escape($locale) ?>][description]"><?= $escape($translation['description']??'') ?></textarea></label></div></section><?php endforeach; ?>
